xql_query:
// ============================================================
// Rule: IPV_New Site Created on WAF
// Vendor: Imperva
// Objective:
// Detect activity associated with IPV_New Site Created on WAF.
// Severity: SEV_020_LOW
// Category: EVASION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1562.001 - Impair Defenses: Disable or Modify Tools

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Motivo: evita perder eventos por variações de caixa em campos como message
config case_sensitive = false

// Fonte de dados: logs brutos do Imperva WAF
// O dataset 'imperva_waf_raw' contém eventos e auditorias geradas pelo WAF, incluindo ações administrativas (audit trail)
| dataset = imperva_waf_raw

// Extração de campos a partir do payload JSON do Imperva
// Observação: o campo 'imperva' (ajuste se necessário) contém o JSON bruto do evento
// - resource_name: nome do recurso/objeto afetado (ex.: hostname/site)
// - account_name: nome da conta/tenant no Imperva
// - executor: e-mail do usuário que executou a ação no console
| alter
    resource_name = json_extract_scalar(imperva, "$.audit_trail.resource_name"), // Ex.: <INTERNAL_DOMAIN_25>.br
    account_name  = json_extract_scalar(imperva, "$.ids.account_name"),          // Ex.: BRA - <ORGANIZATION> - CWAF
    executor      = user -> email                                                // Executor (usuário administrativo)

// Filtro: retorna apenas eventos de criação de site
// O campo 'message' descreve a ação realizada (ex.: "Site created")
| filter message = "Site created"

// Seleção dos campos relevantes para auditoria e notificação do alerta
| fields
    user,           // Objeto 'user' original do evento (pode conter id/nome/email)
    executor,       // E-mail do executor
    account_name,   // Conta/tenant no Imperva
    resource_name,  // Recurso criado (site/hostname)
    message,        // Mensagem do evento (ação)
    imperva         // Payload bruto (útil para evidência e troubleshooting)
